// Archived UI for synthetic regression fixtures only; never used by the operational entrypoint.
import {Inspection} from '../../src/Inspection';
import React,{useEffect,useState} from 'react';
import {createRoot} from 'react-dom/client';
import {request,type Camera,type CameraDetail,type CameraPage,type CameraStatus,type Overview,type Server,type IdentityPage,type IdentityDetail} from '../../src/api';
import '../../src/style.css';
const statusLabels:Record<CameraStatus,string>={operational:'Operativa',down:'Caída',unknown:'Desconocido',inactive:'Inactiva'};
const statusPlural:Record<CameraStatus,string>={operational:'Operativas',down:'Caídas',unknown:'Desconocido',inactive:'Inactivas'};
const queryLabels:Record<string,string>={healthy:'Consultas válidas',partial:'Cobertura parcial',auth_error:'Error de autenticación',http_error:'Error HTTP',transport_error:'Falla de conectividad',invalid_response:'Respuesta inválida',unknown:'Sin observaciones',configuration_error:'Revisar configuración'};
const healthLabels:Record<string,string>={healthy:'En línea',degraded:'Atención',unreachable:'Sin respuesta',unknown:'Sin observaciones',stale:'Datos vencidos'};
function Icon({name,size=20}:{name:string;size?:number}){const paths:Record<string,React.ReactNode>={
  grid:<><rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/></>,
  camera:<><rect x="3" y="6" width="13" height="12" rx="3"/><path d="m16 10 5-3v10l-5-3M7 10h4"/></>,
  server:<><rect x="3" y="3" width="18" height="7" rx="2"/><rect x="3" y="14" width="18" height="7" rx="2"/><path d="M7 6.5h.01M7 17.5h.01M12 6.5h5M12 17.5h5"/></>,
  search:<><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></>,refresh:<><path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 6a8 8 0 0 1 14 6M18 18a8 8 0 0 1-14-6"/></>,
  arrow:<path d="m9 5 7 7-7 7"/>,back:<path d="m15 5-7 7 7 7"/>,check:<path d="m5 12 4 4L19 6"/>,
  alert:<><path d="m12 3 10 18H2L12 3Z"/><path d="M12 9v5M12 17h.01"/></>,clock:<><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></>,
  pulse:<path d="M2 12h5l3-8 4 16 3-8h5"/>,help:<><circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5M12 17h.01"/></>,
};return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[name]??paths.camera}</svg>;}
function useData<T>(path:string,revision:number){const [data,setData]=useState<T|null>(null),[error,setError]=useState(''),[loading,setLoading]=useState(true);
 useEffect(()=>{const controller=new AbortController();setLoading(true);setError('');setData(null);
 request<T>(path,controller.signal).then(setData).catch(e=>{if(e.name!=='AbortError')setError(e.message);}).finally(()=>{if(!controller.signal.aborted)setLoading(false);});
 return()=>controller.abort();},[path,revision]);return {data,error,loading};}
function useLocation(){const [location,setLocation]=useState(window.location.hash.slice(1)||'/dashboard');useEffect(()=>{const change=()=>setLocation(window.location.hash.slice(1)||'/dashboard');window.addEventListener('hashchange',change);return()=>window.removeEventListener('hashchange',change);},[]);return location;}
const date=(value:string|null)=>value?new Intl.DateTimeFormat('es-AR',{dateStyle:'short',timeStyle:'medium',timeZone:'America/Argentina/Buenos_Aires'}).format(new Date(value)):'Sin observaciones';
function age(camera:Camera){if(camera.ageSeconds===null)return 'Nunca observada';if(camera.ageSeconds<60)return `Hace ${camera.ageSeconds} s`;if(camera.ageSeconds<3600)return `Hace ${Math.floor(camera.ageSeconds/60)} min`;return `Hace ${Math.floor(camera.ageSeconds/3600)} h`;}
function Flag({value}:{value:boolean|null}){return <span className={'flag '+(value===null?'null':value?'true':'false')}>{value===null?'Desconocido':value?'Sí':'No'}</span>;}
function Badge({status}:{status:CameraStatus}){return <span className={'badge '+status}><span/>{statusLabels[status]}</span>;}
function ServerBadge({server}:{server:Server}){return <span className={'badge '+(server.health==='healthy'?'operational':server.health==='unreachable'?'down':'unknown')}><span/>{healthLabels[server.health]??'Desconocido'}</span>;}
function Empty({error,loading}:{error?:string;loading?:boolean}){return <div className="empty" role={error?'alert':'status'}><Icon name={error?'alert':loading?'pulse':'search'} size={32}/><strong>{error|| (loading?'Cargando observaciones…':'No encontramos cámaras con esos filtros')}</strong><p>{!error&&!loading?'Probá otro código, servidor o estado.':error?'La interfaz no muestra datos de ejemplo como reemplazo de una conexión fallida.':'Consultando la base de monitoreo.'}</p></div>;}
function CameraTable({items}:{items:Camera[]}){return <div className="table-scroll"><table><thead><tr><th>Cámara / código municipal</th><th>Name técnico</th><th>Servidor</th><th>Estado actual</th><th>Active</th><th>Working</th><th>Última observación</th><th><span className="sr-only">Detalle</span></th></tr></thead><tbody>{items.map(c=><tr key={c.id}><td><a className="camera-link" href={'#/cameras/'+c.id}><span className="camera-icon"><Icon name="camera" size={18}/></span><span><strong>{c.cameraCode??'Sin código confirmado'}</strong><small>{c.description??'Identidad provisional · requiere revisión'}</small></span></a></td><td className="mono">{c.name??'Sin vínculo'}</td><td><span className="server-dot"/>{c.serverName??'Sin servidor'}</td><td><Badge status={c.status}/></td><td><Flag value={c.active}/></td><td><Flag value={c.working}/></td><td className={c.quality==='stale'?'stale-time':''}><span title={date(c.observedAt)}>{age(c)}</span></td><td><a className="row-arrow" href={'#/cameras/'+c.id} aria-label={'Ver detalle de '+(c.cameraCode??c.name)}><Icon name="arrow" size={16}/></a></td></tr>)}</tbody></table></div>;}
function PageTitle({eyebrow,title,description,children}:{eyebrow:string;title:string;description:string;children?:React.ReactNode}){return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div>{children}</div>;}
function ServerCards({items,compact=false}:{items:Server[];compact?:boolean}){return <div className={'server-grid '+(compact?'compact':'')}>{items.map(s=><article className="server-card" key={s.id}><div className="server-card-top"><span className="server-icon"><Icon name="server"/></span><ServerBadge server={s}/></div><h3>{s.name}</h3><p>{queryLabels[s.query]??'Estado desconocido'}</p><div className="server-card-meta"><span>{s.cameraCount} cámaras</span><a href={'#/cameras?server='+s.id}>Ver cámaras <Icon name="arrow" size={13}/></a></div>{!compact&&<div className="server-times"><span>Último intento<strong>{date(s.lastAttemptAt)}</strong></span><span>Última consulta válida<strong>{date(s.lastSuccessAt)}</strong></span><span>Fallos consecutivos<strong>{s.consecutiveFailures}</strong></span></div>}</article>)}</div>;}
function Dashboard({revision}:{revision:number}){const overview=useData<Overview>('overview',revision),cameras=useData<CameraPage>('cameras?pageSize=6',revision);
 if(!overview.data)return <Empty error={overview.error} loading={overview.loading}/>;const d=overview.data;
 const metrics=[{key:'total',title:'Total de cámaras',value:d.total,icon:'camera',hint:`${d.inactive} inactivas · inventario registrado`,status:''},
 {key:'operational',title:'Operativas',value:d.operational,icon:'check',hint:'Observación válida y reciente',status:'operational'},
 {key:'down',title:'Caídas',value:d.down,icon:'alert',hint:'Active sí · Working no · dato reciente',status:'down'},
 {key:'unknown',title:'Estado desconocido',value:d.unknown,icon:'help',hint:'Sin evidencia suficiente o vigente',status:'unknown'},
 {key:'servers',title:'Servidores con problemas',value:d.serversWithProblems,icon:'server',hint:`De ${d.servers.length} servidores registrados`,status:'server'}];
 return <><PageTitle eyebrow="CENTRO DE OPERACIONES" title="Resumen de monitoreo" description="Una vista clara de las cámaras y la infraestructura que las conecta."><span className="as-of"><Icon name="clock" size={16}/> Consultado {new Date(d.generatedAt).toLocaleTimeString('es-AR',{timeZone:'America/Argentina/Buenos_Aires'})}</span></PageTitle>
 {d.total>0&&d.unknown===d.total&&d.servers.every(s=>s.health==='stale')&&<div className="expired-demo"><Icon name="clock"/><div><strong>Las observaciones sintéticas vencieron</strong><p>Para volver al escenario inicial, ejecutá <code>bash ops/demo.sh reset</code>. Actualizar la vista no genera observaciones.</p></div></div>}
 <div className="metrics">{metrics.map(m=><a key={m.key} href={m.key==='servers'?'#/servers':'#/cameras'+(m.status?'?status='+m.status:'')} className={'metric '+m.status}><div className="metric-label">{m.title}<Icon name={m.icon} size={19}/></div><strong>{m.value.toString().padStart(2,'0')}</strong><small>{m.hint}</small></a>)}</div>
 <div className="overview-grid"><section className="panel"><div className="panel-heading"><div><h2>Distribución de estados</h2><p>La incertidumbre también es información.</p></div><Icon name="pulse"/></div><div className="distribution-total"><strong>{d.total}</strong><span>cámaras en inventario</span></div><div className="distribution-bar">{(['operational','down','unknown','inactive'] as const).map(k=>d[k]>0&&<div key={k} className={k} style={{width:(100*d[k]/d.total)+'%'}} title={statusPlural[k]+': '+d[k]}/>)}</div><div className="distribution-legend">{(['operational','down','unknown','inactive'] as const).map(k=><a key={k} href={'#/cameras?status='+k}><i className={k}/>{statusPlural[k]}<strong>{d[k]}</strong></a>)}</div></section>
 <section className="quality-note"><span className="note-icon"><Icon name="check" size={24}/></span><div className="eyebrow">LECTURAS CON CONTEXTO</div><h2>Una falla de servidor<br/>no es una cámara caída.</h2><p>Conservamos el último estado conocido. Si la observación vence o el servidor falla, el estado actual se muestra como desconocido.</p><a href="#/servers">Revisar infraestructura <Icon name="arrow" size={15}/></a></section></div>
 <section className="section"><div className="section-heading"><div><h2>Inventario de cámaras</h2><p>Estado, origen y última observación en una sola vista.</p></div><a className="text-link" href="#/cameras">Ver todas las cámaras <Icon name="arrow" size={15}/></a></div><div className="panel table-panel">{cameras.data?<CameraTable items={cameras.data.items}/>:<Empty error={cameras.error} loading={cameras.loading}/>}</div></section>
 <section className="section"><div className="section-heading"><div><h2>Infraestructura</h2><p>Disponibilidad de los servidores, independiente de sus cámaras.</p></div><a className="text-link" href="#/servers">Ver servidores <Icon name="arrow" size={15}/></a></div><ServerCards items={d.servers} compact/></section></>;}
function Cameras({revision,search}:{revision:number;search:string}){const initial=new URLSearchParams(search);const [q,setQ]=useState(initial.get('q')??''),[server,setServer]=useState(initial.get('server')??''),[status,setStatus]=useState(initial.get('status')??''),[page,setPage]=useState(1),[debounced,setDebounced]=useState(q);
 useEffect(()=>{const p=new URLSearchParams(search);setServer(p.get('server')??'');setStatus(p.get('status')??'');setPage(1);},[search]);
 useEffect(()=>{const timer=setTimeout(()=>setDebounced(q),200);return()=>clearTimeout(timer);},[q]);
 const params=new URLSearchParams({q:debounced,server,status,page:String(page),pageSize:'12'});const data=useData<CameraPage>('cameras?'+params,revision),servers=useData<{items:Server[]}>('servers',revision);
 return <><PageTitle eyebrow="INVENTARIO" title="Cámaras" description="Buscá una cámara y revisá la evidencia detrás de su estado."/>
 <section className="panel table-panel"><div className="filters"><label className="search"><Icon name="search" size={18}/><span className="sr-only">Buscar cámaras</span><input value={q} onChange={e=>{setQ(e.target.value);setPage(1);}} placeholder="Buscar código, Name o descripción…" maxLength={100}/></label><label><span className="sr-only">Servidor</span><select value={server} onChange={e=>{setServer(e.target.value);setPage(1);}}><option value="">Todos los servidores</option>{servers.data?.items.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label><label><span className="sr-only">Estado</span><select value={status} onChange={e=>{setStatus(e.target.value);setPage(1);}}><option value="">Todos los estados</option>{Object.entries(statusPlural).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></label>{(q||server||status)&&<button className="button quiet" onClick={()=>{setQ('');setServer('');setStatus('');setPage(1);}}>Limpiar</button>}</div>
 {data.loading||data.error?<Empty loading={data.loading} error={data.error}/>:data.data?.items.length?<CameraTable items={data.data.items}/>:<Empty/>}
 <div className="pagination"><span>{data.data?.total??0} cámaras encontradas</span><div><button className="button quiet" disabled={page===1||data.loading} onClick={()=>setPage(p=>p-1)}>Anterior</button><span>Página {page} de {Math.max(1,Math.ceil((data.data?.total??0)/12))}</span><button className="button quiet" disabled={data.loading||page*12>=(data.data?.total??0)} onClick={()=>setPage(p=>p+1)}>Siguiente</button></div></div></section><p className="footnote">Los códigos sin confirmar se muestran como tales. Active y Working conservan su valor observado, incluso cuando el estado actual es desconocido.</p></>;}
const reasons:Record<string,string>={initial:'Primera observación',state_changed:'Cambio de estado',resumed:'Observación reanudada',coverage_changed:'Cambio de cobertura',binding_changed:'Cambio de vínculo'};
const qualityText:Record<string,string>={operational:'La cámara está activa y Working es verdadero en una observación reciente.',down:'La cámara está activa y Working es falso. La cobertura es válida y la observación es reciente.',inactive:'La última observación válida indica que la cámara está inactiva.',future_observation:'La marca temporal es posterior al momento de consulta. El estado actual no puede confirmarse.',never_seen:'Todavía no hay observaciones para esta cámara.',stale:'La última observación superó los 3 minutos de vigencia. No confirma el estado actual.',server_problem:'El servidor tiene problemas de consulta. Se conserva el último estado conocido, sin afirmar el estado actual.',incomplete:'No hay cobertura suficiente de estado para confirmar el funcionamiento.',unknown_flags:'La observación no contiene todas las banderas necesarias para clasificar el estado actual.'};
function Detail({id,revision}:{id:string;revision:number}){const detail=useData<CameraDetail>('cameras/'+id,revision);if(!detail.data)return <Empty error={detail.error} loading={detail.loading}/>;const c=detail.data;
 return <><a className="back-link" href="#/cameras"><Icon name="back" size={15}/> Volver a cámaras</a><PageTitle eyebrow="DETALLE DE CÁMARA" title={c.cameraCode??'Identidad provisional'} description={c.description??'Sin descripción disponible'}><Badge status={c.status}/></PageTitle>
 <div className={'status-explanation '+c.status}><Icon name={c.status==='down'?'alert':'help'}/><div><strong>{statusLabels[c.status]}</strong><p>{qualityText[c.quality]??qualityText.unknown_flags}</p></div></div>
 <div className="detail-grid"><section className="panel"><div className="panel-heading"><h2>Identidad e inventario</h2><Icon name="camera"/></div><dl><div><dt>Código municipal</dt><dd>{c.cameraCode??<span className="provisional">Sin confirmar · cámara provisional</span>}</dd></div><div><dt>Name técnico original</dt><dd className="mono">{c.name??'Sin vínculo'}</dd></div><div><dt>Servidor</dt><dd><a href="#/servers">{c.serverName??'Sin servidor'}</a></dd></div><div><dt>Descripción</dt><dd>{c.description??'Sin descripción'}</dd></div></dl></section>
 <section className="panel"><div className="panel-heading"><h2>Última observación</h2><Icon name="clock"/></div><div className="flag-cards"><div><small>Active</small><Flag value={c.active}/></div><div><small>Working</small><Flag value={c.working}/></div></div><dl><div><dt>Recibida</dt><dd>{date(c.observedAt)}</dd></div><div><dt>Antigüedad al consultar</dt><dd>{age(c)}</dd></div><div><dt>Cobertura de estado</dt><dd>{c.coverage==='matched'?'Coincidente':c.coverage==='missing'?'Estado no recibido':'Desconocida'}</dd></div><div><dt>Fuente de Active</dt><dd>{c.activeSource==='status'?'GetStatus':c.activeSource==='inventory'?'GetCameras':'Sin observación'}</dd></div></dl></section></div>
 <section className="section"><div className="section-heading"><div><h2>Historial de estados</h2><p>Transiciones observadas. No representan una grabación continua ni confirman el estado actual.</p></div><span className="count-badge">{c.events.length} eventos</span></div><div className="panel history">{c.events.length?c.events.map((e,i)=><article className="history-event" key={e.id}><span className={'timeline-dot '+(i===0?'latest':'')}/><div><div className="event-top"><h3>{reasons[e.reason]??'Observación registrada'}</h3><time>{date(e.observedAt)}</time></div><p>{e.serverName} · {e.coverage==='matched'?'Estado coincidente':'Cobertura incompleta'}</p><div className="event-flags"><span>Active <Flag value={e.active}/></span><span>Working <Flag value={e.working}/></span></div></div></article>):<Empty/>}</div></section></>;}
function Servers({revision}:{revision:number}){const {data,error,loading}=useData<{items:Server[]}>('servers',revision);return <><PageTitle eyebrow="INFRAESTRUCTURA" title="Servidores" description="La salud de la consulta no se confunde con el funcionamiento de las cámaras."/>{data?<><ServerCards items={data.items}/><div className="info-panel"><Icon name="help"/><div><h3>Cómo leer esta vista</h3><p>Un error de autenticación significa que el servidor respondió. “Sin respuesta” es una condición de transporte separada. Ninguna de ellas convierte las cámaras en Working = No.</p></div></div></>:<Empty error={error} loading={loading}/>}</>;}
const identityKinds:Record<string,string>={unconfirmed_code:'Sin código confirmado',duplicate_code:'Candidato duplicado',confirmed_code_mismatch:'Código observado diferente',possible_rename:'Posible cambio de Name',possible_replacement:'Posible reemplazo'};
const reviewStates:Record<string,string>={pending:'Pendiente',approved:'Aprobado',rejected:'Rechazado',resolved:'Resuelto'};
function Identities({revision,search,id}:{revision:number;search:string;id?:string}){
 const params=new URLSearchParams(search),kind=params.get('kind')??'',server=params.get('server')??'',state=params.get('state')??'';
 const page=Number(params.get('page')??1);
 const result=useData<IdentityPage|IdentityDetail>(id?'identities/'+id:'identities?'+params.toString(),revision);
 const list={...result,data:result.data as IdentityPage|null},detail={...result,data:result.data as IdentityDetail|null};
 const servers=useData<{items:Server[]}>('servers',revision);
 function filter(key:string,value:string){const next=new URLSearchParams(search);next.set(key,value);next.delete('page');window.location.hash='/identities?'+next.toString();}
 return <><PageTitle eyebrow="REVISIÓN DE CÁMARAS" title="Identidades" description="Evidencia municipal y técnica, sin correcciones automáticas."/>
 <div className="info-panel"><Icon name="help"/><div><h3>Solo lectura</h3><p>Detectar una incidencia no autoriza corregir una identidad. No se asignan códigos, no se fusionan cámaras y no se traslada historial.</p></div></div>
 {id?<><a className="back-link" href="#/identities">← Volver a incidencias</a>{detail.data?<IdentityEvidence incident={detail.data}/>:<Empty error={detail.error} loading={detail.loading}/>}</>:<>
 <div className="filters identity-filters"><label>Tipo<select aria-label="Tipo de incidencia" value={kind} onChange={e=>filter('kind',e.target.value)}><option value="">Todos los tipos</option>{Object.entries(identityKinds).map(([k,v])=><option value={k} key={k}>{v}</option>)}</select></label>
 <label>Servidor<select aria-label="Servidor de incidencia" value={server} onChange={e=>filter('server',e.target.value)}><option value="">Todos los servidores</option>{servers.data?.items.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label>
 <label>Estado<select aria-label="Estado de revisión" value={state} onChange={e=>filter('state',e.target.value)}><option value="">Todos los estados</option>{Object.entries(reviewStates).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label></div>
 {list.data?<section className="section"><div className="section-heading"><div><h2>Incidencias de identidad</h2><p>Los candidatos nuevos provienen de Description; las propuestas históricas conservan su fuente. Name sigue siendo la clave técnica.</p></div><span className="count-badge">{list.data.total} incidencias</span></div>
 <div className="identity-list">{list.data.items.length?list.data.items.map(x=><article className="panel identity-card" key={x.id}><div className="identity-card-top"><span className="provisional">{identityKinds[x.kind]}</span><span className="count-badge">{reviewStates[x.state]}</span></div>
 <h3><a href={'#/cameras/'+x.cameraId}>{x.currentConfirmedCode??'Cámara provisional'}</a></h3><p className="mono identity-name">{x.name??'Sin vínculo técnico'}</p><p>{x.serverName??'Sin servidor'}</p>
 <dl><div><dt>Candidato desde {x.codeSource??'Name (legado)'}</dt><dd className="mono">{x.candidateCode??'Sin código válido'}</dd></div><div><dt>Código confirmado al detectar</dt><dd>{x.confirmedCode??'Sin confirmar'}</dd></div><div><dt>Origen</dt><dd>{x.source==='operator'?'Hipótesis explícita':x.source==='inventory'?'Inventario actual':'Detección automática'}</dd></div></dl>
 <a className="identity-evidence-link" href={'#/identities/'+x.id}>Ver evidencia →</a></article>):<div className="panel"><p>No hay incidencias para estos filtros.</p></div>}</div>
 <div className="pagination"><span>Página {page} · {list.data.total} resultados</span><div><button className="button" disabled={page<=1} onClick={()=>{params.set('page',String(page-1));window.location.hash='/identities?'+params;}}>Anterior</button><button className="button" disabled={page*20>=list.data.total} onClick={()=>{params.set('page',String(page+1));window.location.hash='/identities?'+params;}}>Siguiente</button></div></div></section>:<Empty error={list.error} loading={list.loading}/>}</>}
 </>;
}
function IdentityEvidence({incident:x}:{incident:IdentityDetail}){return <section className="section"><div className="section-heading"><div><h2>{identityKinds[x.kind]}</h2><p>{reviewStates[x.state]} · {x.stateSource==='derived'?'Condición actual del inventario; no es una decisión registrada.':'Propuesta registrada con evidencia histórica.'}</p></div></div>
 <div className="detail-grid"><section className="panel"><h3>Cámara observada</h3><dl><div><dt>Cámara</dt><dd><a href={'#/cameras/'+x.cameraId}>{x.currentConfirmedCode??'Identidad provisional'} →</a></dd></div><div><dt>Name exacto</dt><dd className="mono identity-name">{x.name??'Sin vínculo técnico'}</dd></div><div><dt>Servidor</dt><dd>{x.serverName}</dd></div><div><dt>Candidato observado</dt><dd>{x.candidateCode??'Sin código válido'}</dd></div><div><dt>Confirmado al detectar</dt><dd>{x.confirmedCode??'Sin confirmar'}</dd></div><div><dt>Detectado</dt><dd>{date(x.detectedAt)}</dd></div></dl></section>
 <section className="panel"><h3>Evidencia y procedencia</h3><p className="identity-note">Un Name diferente no demuestra continuidad física. Un reemplazo puede recibir un código nuevo. Description es la fuente oficial; Name no se utiliza como fallback.</p>{x.relatedCameraId&&<p>Cámara relacionada: <a href={'#/cameras/'+x.relatedCameraId}>{x.relatedName??x.relatedCameraId}</a> · candidato {x.relatedCandidateCode??'sin código'}</p>}
 <dl><div><dt>Versión de inventario</dt><dd className="mono identity-ref">{x.inventoryId??'Sin versión de inventario'}</dd></div><div><dt>Ejecución de origen</dt><dd className="mono identity-ref">{x.serverRunId??'Sin referencia disponible'}</dd></div><div><dt>Revisión</dt><dd>{x.revision??'No corresponde'}</dd></div></dl></section></div>
 <section className="panel identity-audit"><h3>Observaciones registradas</h3>{x.evidence.length?x.evidence.map(e=><article key={e.id}><strong>{e.code}</strong><p>{date(e.recordedAt)}</p><p className="mono identity-ref">Ejecución: {e.serverRunId}</p></article>):<p>La evidencia disponible es la versión de inventario referenciada; no hay incidencias de sincronización asociadas.</p>}</section>
 <section className="panel identity-audit"><h3>Auditoría de revisión</h3>{x.decisions.length?x.decisions.map(e=><article key={e.revision}><strong>{e.action==='reject'?'Rechazo registrado':'Nota registrada'}</strong><p>{e.reasonCode} · {date(e.decidedAt)}</p><p className="mono identity-ref">Operador: {e.operatorId} · revisión {e.revision}</p></article>):<p>No hay decisiones registradas. Esta interfaz no permite aprobar, rechazar ni aplicar modificaciones.</p>}</section></section>;}
function App(){const location=useLocation(),[path,search='']=location.split('?'),[revision,setRevision]=useState(0),[now,setNow]=useState(new Date());
 useEffect(()=>{document.title=path==='/inspection'?'Digifort Monitor · Inspección local':'Digifort Monitor · Demostración';},[path]);
 // Re-read PostgreSQL to recalculate freshness; this never polls Digifort or writes observations.
 useEffect(()=>{const timer=setInterval(()=>{setRevision(r=>r+1);setNow(new Date());},30000);return()=>clearInterval(timer);},[]);
 const demoOrigin=import.meta.env.VITE_DEMO_ORIGIN??'http://127.0.0.1:8082';
 const inspectionOrigin=import.meta.env.VITE_INSPECTION_ORIGIN??'http://127.0.0.1:8083';
 const navHref=(id:string)=>id==='inspection'?(path==='/inspection'?'#/inspection':inspectionOrigin+'/#/inspection'):(path==='/inspection'?demoOrigin+'/#/'+id:'#/'+id);
 const section=path==='/inspection'?'inspection':path.startsWith('/identities')?'identities':path.startsWith('/cameras')?'cameras':path==='/servers'?'servers':'dashboard';
 return <div className="app-shell"><aside className="sidebar"><a href={navHref('dashboard')} className="brand"><span className="brand-mark"><Icon name="camera" size={24}/></span><span>digifort<span className="brand-sub">MONITOR</span></span></a><div className="workspace-label">ESPACIO DE TRABAJO</div><div className="workspace"><span className="workspace-avatar">M</span><div>Monitoreo municipal<small>{section==='inspection'?'Inspección temporal':'Entorno de demostración'}</small></div></div><div className="nav-label">SUPERVISIÓN</div><nav aria-label="Navegación principal">{[{id:'dashboard',icon:'grid',label:'Dashboard'},{id:'cameras',icon:'camera',label:'Cámaras'},{id:'servers',icon:'server',label:'Servidores'},{id:'identities',icon:'help',label:'Identidades'},{id:'inspection',icon:'search',label:'Inspección Digifort'}].map(item=><a key={item.id} href={navHref(item.id)} className={section===item.id?'active':''} aria-current={section===item.id?'page':undefined}><Icon name={item.icon}/>{item.label}{section===item.id&&<span className="nav-active-dot"/>}</a>)}</nav><div className="sidebar-footer"><span className="demo-indicator"/> {section==='inspection'?'INSPECCIÓN LOCAL':'DEMO LOCAL'}<small>{section==='inspection'?'Lectura real · sólo en memoria':'Datos sintéticos · sin conexión a Digifort'}</small><div className="sidebar-version">MVP visual <span>v0.1</span></div></div></aside>
 <div className="app-body"><header className="topbar"><div className="breadcrumb">Supervisión <span>/</span><strong>{section==='inspection'?'Inspección Digifort':section==='dashboard'?'Dashboard':section==='cameras'?'Cámaras':section==='identities'?'Identidades':'Servidores'}</strong></div><div className="topbar-actions"><span className="local-clock">{now.toLocaleDateString('es-AR',{day:'2-digit',month:'short',timeZone:'America/Argentina/Buenos_Aires'})} · Argentina</span><span className="avatar">DM</span></div></header><main>{section==='inspection'?<div className="demo-banner"><span><span className="demo-tag">LECTURA REAL</span> Sólo GetCameras · sin persistencia · sin sincronización automática.</span></div>:<div className="demo-banner"><span><span className="demo-tag">DEMOSTRACIÓN</span> Datos sintéticos. Sin conexión a servidores Digifort reales.</span><button className="button" onClick={()=>{setRevision(r=>r+1);setNow(new Date());}}><Icon name="refresh" size={15}/> Actualizar vista</button></div>}
 {section==='inspection'?<Inspection/>:section==='identities'?<Identities key={path} revision={revision} search={search} id={path.startsWith('/identities/')?path.slice('/identities/'.length):undefined}/>:path.startsWith('/cameras/')?<Detail id={path.slice('/cameras/'.length)} revision={revision}/>:section==='cameras'?<Cameras revision={revision} search={search}/>:section==='servers'?<Servers revision={revision}/>:<Dashboard revision={revision}/>}
 <footer className="content-footer"><span>{section==='inspection'?'Datos reales temporales · Sin video en vivo':'Datos sintéticos · Sin video en vivo'}</span><span><Icon name="clock" size={13}/> {section==='inspection'?'La inspección sólo consulta Digifort por acción manual.':'Vigencia: 3 minutos · La vista se recalcula cada 30 s, sin generar observaciones.'}</span></footer></main></div></div>;}
export {App as LegacyMonitor};
